INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (1, "カリン", 1, 62, 1, 2, 1000001, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 3.414, -416.5, "2030/01/01 14:59:59", 190801, "2025/01/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (1, "カリン", 2, 62, 1, 2, 1000002, "ミッションをクリアして、\n報酬をゲットしましょう！", 3.099, -416.5, "2030/01/01 14:59:59", 190801, "2025/01/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (1, "カリン", 3, 63, 1, 2, 1000003, "受け取ることができる\n報酬があるようです\n確認してみてください", 2.801, -416.5, "2030/01/01 14:59:59", 190801, "2025/01/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (1, "カリン", 4, 63, 2, 2, 1000004, "報酬がもらえますよ！\nチェックしてみてください", 0, -416.5, "2030/01/01 14:59:59", 190801, "2025/01/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (1, "カリン", 5, 64, 2, 1, 1000005, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 2.12, -363, "2030/01/01 14:59:59", 190801, "2025/01/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (1, "カリン", 6, 64, 1, 2, 1000006, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 1.68, -363, "2030/01/01 14:59:59", 190801, "2025/01/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (1, "カリン", 7, 64, 2, 1, 1000007, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 2.33, -363, "2030/01/01 14:59:59", 190801, "2025/01/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10201, "ラビリスタ", 101, 61, 3, 7, 1020101, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 5.18, -285, "2030/01/01 14:59:59", 133701, "2025/01/31 12:00:00", -6);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10201, "クリスティーナ", 201, 61, 1, 2, 1020102, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 8.77, -285, "2030/01/01 14:59:59", 133901, "2025/01/31 12:00:00", -2);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10201, "ネネカ", 301, 61, 6, 1, 1020103, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 15.5, -285, "2030/01/01 14:59:59", 133801, "2025/01/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10202, "ランファ", 101, 61, 2, 5, 1020201, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 9.061, -285, "2030/01/01 14:59:59", 134301, "2025/02/28 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10202, "チカ", 201, 61, 1, 2, 1020202, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 7.699, -285, "2030/01/01 14:59:59", 134401, "2025/02/28 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10203, "アオイ", 101, 61, 1, 2, 1020301, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 8.595, -285, "2030/01/01 14:59:59", 134601, "2025/03/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10203, "クローチェ", 201, 61, 1, 2, 1020302, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 7.758, -285, "2030/01/01 14:59:59", 134501, "2025/03/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10204, "ルイズマリー", 101, 61, 2, 6, 1020401, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 7, -285, "2030/01/01 14:59:59", 132302, "2025/04/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10204, "イロハ", 201, 61, 1, 2, 1020402, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 7.904, -285, "2030/01/01 14:59:59", 132402, "2025/04/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10204, "ソノ", 301, 61, 4, 2, 1020403, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 8.487, -285, "2030/01/01 14:59:59", 132502, "2025/04/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10205, "カノン", 101, 61, 1, 2, 1020502, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 8.763, -285, "2030/01/01 14:59:59", 134901, "2025/05/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10205, "ツムギ", 201, 61, 1, 3, 1020503, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 6.417, -285, "2030/01/01 14:59:59", 134801, "2025/05/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10206, "エリス", 101, 61, 3, 7, 1020601, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 10.335, -285, "2030/01/01 14:59:59", 135001, "2025/06/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10206, "シェフィ", 201, 61, 2, 4, 1020602, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 6.281, -285, "2030/01/01 14:59:59", 135101, "2025/06/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10206, "プレシア", 301, 61, 1, 2, 1020603, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 12.244, -285, "2030/01/01 14:59:59", 135201, "2025/06/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10207, "クリア", 101, 61, 2, 8, 1020701, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 6.339, -285, "2030/01/01 14:59:59", 135301, "2025/07/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10207, "アネモネ", 201, 61, 7, 9, 1020702, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 8.184, -285, "2030/01/01 14:59:59", 135401, "2025/07/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10208, "アイラ", 101, 61, 9, 2, 1020801, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 3.906, -285, "2030/01/01 14:59:59", 129101, "2025/08/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10208, "シナツ", 201, 61, 1, 2, 1020802, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 14.465, -285, "2030/01/01 14:59:59", 129201, "2025/08/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10208, "ヒヨリ", 301, 61, 4, 3, 1020803, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 8.662, -285, "2030/01/01 14:59:59", 100101, "2025/08/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10208, "レイ", 401, 61, 1, 3, 1020804, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 10.915, -285, "2030/01/01 14:59:59", 100301, "2025/08/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10209, "ユキノ", 101, 61, 1, 7, 1020901, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 6.042, -285, "2030/01/01 14:59:59", 135802, "2025/09/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10209, "サツキ", 201, 61, 4, 1, 1020902, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 9.402, -285, "2030/01/01 14:59:59", 135903, "2025/09/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10209, "ルルィ", 301, 61, 8, 1, 1020903, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 8.16, -285, "2030/01/01 14:59:59", 136902, "2025/09/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10210, "カスミ", 101, 61, 3, 2, 1021001, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 5, -285, "2030/01/01 14:59:59", 137401, "2025/10/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10210, "アラクネ", 201, 61, 4, 1, 1021002, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 8.12, -285, "2030/01/01 14:59:59", 136001, "2025/10/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10210, "ナーナ", 301, 61, 4, 2, 1021003, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 6.386, -285, "2030/01/01 14:59:59", 136202, "2025/10/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10211, "ユイ", 101, 61, 3, 4, 1021101, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 7.438, -285, "2030/01/01 14:59:59", 136402, "2025/11/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10211, "ミソラ", 201, 61, 1, 5, 1021102, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 8.35, -285, "2030/01/01 14:59:59", 136302, "2025/11/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10212, "シズル", 101, 61, 1, 2, 1021201, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 5, -285, "2030/01/01 14:59:59", 136501, "2025/12/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10212, "リノ", 201, 61, 1, 2, 1021202, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 5.25, -285, "2030/01/01 14:59:59", 137902, "2025/12/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10212, "ラビリスタ", 301, 61, 1, 2, 1021203, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 7.5, -285, "2030/01/01 14:59:59", 106801, "2025/12/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10213, "ライラエル", 101, 61, 1, 2, 1021301, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 8.204, -285, "2030/01/01 14:59:59", 126501, "2026/01/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10213, "ネフィ＝ネラ", 201, 61, 1, 2, 1021302, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 7.176, -285, "2030/01/01 14:59:59", 129701, "2026/01/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10213, "ヴァイオレット", 301, 61, 1, 5, 1021303, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 8.602, -285, "2030/01/01 14:59:59", 133101, "2026/01/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10213, "ライラエル", 102, 61, 1, 3, 1021304, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 10.14, -285, "2030/01/01 14:59:59", 138101, "2026/02/06 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10213, "ネフィ＝ネラ", 202, 61, 1, 7, 1021305, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 10.152, -285, "2030/01/01 14:59:59", 138201, "2026/02/06 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10213, "ヴァイオレット", 302, 61, 4, 3, 1021306, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 9.688, -285, "2030/01/01 14:59:59", 138001, "2026/02/06 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10213, "ペコリーヌ", 401, 61, 2, 1, 1021307, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 5.928, -285, "2030/01/01 14:59:59", 138301, "2026/02/12 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10214, "ワカナ", 101, 61, 4, 2, 1021401, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 9.19, -285, "2030/01/01 14:59:59", 138702, "2026/02/28 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10214, "シオリ", 201, 61, 1, 3, 1021402, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 8.724, -285, "2030/01/01 14:59:59", 138802, "2026/02/28 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10215, "グレイス", 101, 61, 4, 1, 1021501, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 7.758, -285, "2030/01/01 14:59:59", 138902, "2026/03/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10215, "キョウカ", 201, 61, 6, 4, 1021502, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 6.375, -285, "2030/01/01 14:59:59", 139002, "2026/03/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10215, "ルルィ", 301, 61, 6, 1, 1021503, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 6.173, -285, "2030/01/01 14:59:59", 136902, "2026/03/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10216, "ミホ", 101, 61, 6, 2, 1021601, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 4.202, -285, "2030/01/01 14:59:59", 139202, "2026/04/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10216, "マホ", 201, 61, 6, 1, 1021602, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 2.842, -285, "2030/01/01 14:59:59", 139302, "2026/04/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10216, "エリカ", 301, 61, 4, 1, 1021603, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 4.598, -285, "2030/01/01 14:59:59", 139402, "2026/04/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10217, "リリ", 101, 61, 4, 3, 1021701, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 6.533, -285, "2030/01/01 14:59:59", 125802, "2026/05/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10217, "プレシア", 301, 61, 3, 3, 1021702, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 5, -285, "2030/01/01 14:59:59", 126102, "2026/05/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10217, "クリア", 201, 61, 3, 4, 1021703, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 5.214, -285, "2030/01/01 14:59:59", 126002, "2026/05/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10217, "リリ", 102, 61, 1, 3, 1021704, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 8.781, -285, "2030/01/01 14:59:59", 139501, "2026/05/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10217, "クリア", 202, 61, 2, 1, 1021705, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 6.529, -285, "2030/01/01 14:59:59", 139601, "2026/05/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10217, "プレシア", 302, 61, 3, 2, 1021706, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 3.195, -285, "2030/01/01 14:59:59", 139701, "2026/05/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10218, "ルイズマリー", 101, 61, 2, 3, 1021801, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 12.43, -285, "2030/01/01 14:59:59", 139902, "2026/06/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10218, "クレジッタ", 201, 61, 2, 3, 1021802, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 6.35, -285, "2030/01/01 14:59:59", 140001, "2026/06/30 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10219, "フブキ", 101, 61, 1, 5, 1021901, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 10.23, -285, "2030/01/01 14:59:59", 140102, "2026/07/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10219, "ヴァンピィ", 201, 61, 1, 2, 1021902, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 5.584, -285, "2030/01/01 14:59:59", 140201, "2026/07/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10220, "クローチェ", 201, 61, 6, 3, 1022001, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", 2.8, -285, "2030/01/01 14:59:59", 126401, "2026/08/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10220, "ヴルム", 101, 61, 4, 3, 1022002, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", 8.9, -285, "2030/01/01 14:59:59", 127802, "2026/08/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10220, "クローチェ", 202, 61, 2, 1, 1022003, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", 4.49, -285, "2030/01/01 14:59:59", 140602, "2026/08/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10220, "ヴルム", 102, 61, 1, 3, 1022004, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", 9.42, -285, "2030/01/01 14:59:59", 140501, "2026/08/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10220, "リーザ", 301, 61, 4, 1, 1022005, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", 7, -285, "2030/01/01 14:59:59", 140402, "2026/08/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10221, "アーモンドアイ", 101, 61, 1, 3, 1022101, "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", 8.61, -285, "2030/01/01 14:59:59", 141101, "2026/10/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10221, "ラッキーライラック", 201, 61, 6, 1, 1022102, "ゴルシさんは相変わらずやねぇ…\nまぁせっかくの異世界やし\nいつもと違うレース、\n楽しませてもらいましょ", 3.55, -285, "2030/01/01 14:59:59", 141201, "2026/10/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10221, "デアリングタクト", 301, 61, 2, 1, 1022103, "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", 8.26, -285, "2030/01/01 14:59:59", 141301, "2026/10/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10221, "ゴールドシップ", 401, 61, 2, 1, 1022104, "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", 8.79, -285, "2030/01/01 14:59:59", 141001, "2026/10/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10221, "アーモンドアイ", 101, 61, 1, 3, 1022105, "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", 8.61, -285, "2030/01/01 14:59:59", 141101, "2026/10/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10221, "ラッキーライラック", 202, 61, 1, 2, 1022106, "（剣と魔法！　ええなぁ～！\nうちも魔法覚えられるやろか\nレースの後に花咲かせたり…\nくぅ～っ！　はよ試したいわ！）", 2.69, -285, "2030/01/01 14:59:59", 141201, "2026/10/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10221, "デアリングタクト", 301, 61, 2, 1, 1022107, "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", 8.26, -285, "2030/01/01 14:59:59", 141301, "2026/10/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10221, "ゴールドシップ", 401, 61, 2, 1, 1022108, "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", 8.79, -285, "2030/01/01 14:59:59", 141001, "2026/10/31 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2, "カリン", 1, 62, 1, 2, 2000001, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 3.414, -416.5, "2030/01/01 14:59:59", 190805, "2026/04/10 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2, "カリン", 2, 62, 1, 2, 2000002, "ミッションをクリアして、\n報酬をゲットしましょう！", 3.099, -416.5, "2030/01/01 14:59:59", 190805, "2026/04/10 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2, "カリン", 3, 63, 1, 2, 2000003, "受け取ることができる\n報酬があるようです\n確認してみてください", 2.801, -416.5, "2030/01/01 14:59:59", 190805, "2026/04/10 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2, "カリン", 4, 63, 2, 2, 2000004, "報酬がもらえますよ！\nチェックしてみてください", 0, -416.5, "2030/01/01 14:59:59", 190805, "2026/04/10 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2, "カリン", 5, 64, 2, 1, 2000005, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 2.12, -363, "2030/01/01 14:59:59", 190805, "2026/04/10 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2, "カリン", 6, 64, 1, 2, 2000006, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 1.68, -363, "2030/01/01 14:59:59", 190805, "2026/04/10 12:00:00", 0);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2, "カリン", 7, 64, 2, 1, 2000007, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 2.33, -363, "2030/01/01 14:59:59", 190805, "2026/04/10 12:00:00", 0);
